    ["OMI (omi.1x.webpage.7921.txt, 1979–2021 version)", "NOAA interpolated OLR, 20–96-day filter; EOFs from 1979–2012", "None beyond filtering", "All months", f"NOAA PSL {c('kiladis2014', 'psl')}"],
