    [f"Firing et al. 1983 {c('firing1983')}", "Abstract", "Undercurrent at 159°W decayed Aug, partly reversed Sep, reappeared Jan 1983", "Yes. The link to westerly winds is the authors' stated interpretation (‘consistent with’)", "None found", "Kept"],
    [f"Luther et al. 1983 {c('luther1983')}", "Abstract", "Bursts of 1–3 weeks precede El Niño", "Yes for 1950–78 (all events except 1963); says bursts ‘may’ force Kelvin waves; nothing on 1982 or the MJO", "None found", "Reworded; MJO statement now cited to MJO studies"],
    [f"Harrison 1984 {c('harrison1984')}", "Abstract", "June southerly band at 150°–160°E, then sustained westerlies; trigger of the vigorous phase", "Yes, as the author's interpretation (‘appears to be an important component’)", "None found", "Kept as ‘proposed’"],
